import type { Address, RewardModule, StakingConfig } from '~/types/stakingConfig'

const rewards: RewardModule = {
    // Wire real distributor in a follow-up; placeholder for labels-driven UI
    async getClaims() {
        return []
    },
}

export const kiteConfig: StakingConfig = {
    namespace: 'kite',
    labels: { token: 'KITE', stToken: 'stKITE', stakeVerb: 'Stake' },
    addresses: {
        stakeToken: import.meta.env.VITE_KITE_ADDRESS as unknown as Address,
        stToken: import.meta.env.VITE_STAKING_TOKEN_ADDRESS as unknown as Address,
        manager: import.meta.env.VITE_STAKING_MANAGER as unknown as Address,
    },
    decimals: 18,
    cooldownSeconds: 21 * 24 * 60 * 60,
    affectsBoost: true,
    subgraph: {
        poolKey: 'kite',
        userEntity: 'stakingUser',
        statsEntity: 'stakingStatistic',
        idForUser: (a: string) => a.toLowerCase(),
        idForStats: () => 'singleton',
    },
    rewards,
}

src/services/stakingService.ts.content:
import { Contract, BigNumber, utils } from 'ethers'
import { Provider } from '@ethersproject/providers'
import { contracts } from '~/config/contracts'
import { parseEther } from 'ethers/lib/utils'

export type Address = `0x${string}`
export type EtherString = string

function toEtherString(value: BigNumber): EtherString {
    return utils.formatEther(value)
}

export function buildStakingService(
    managerAddress: Address,
    abi: any = contracts.abis.stakingManager,
    decimals: number = 18
) {
    const sm = (signerOrProvider: any) => new Contract(managerAddress, abi, signerOrProvider)

    return {
        decimals,
        async getTotalStaked(provider: Provider): Promise<EtherString> {
            const total: BigNumber = await sm(provider).totalStaked()
            return toEtherString(total)
        },
        async getStakedBalance(address: Address | undefined, provider: Provider): Promise<EtherString> {
            if (!address) return toEtherString(BigNumber.from(0))
            const bal: BigNumber = await sm(provider).stakedBalances(address)
            return toEtherString(bal)
        },
        async getCooldown(provider: Provider): Promise<number> {
            const seconds: BigNumber = await sm(provider)._params()
            return seconds.toNumber()
        },
        async getRewards(address: Address | undefined, provider: Provider): Promise<AggregatedReward[]> {
            if (!address) return []
            const rewardsCountBn: BigNumber = await sm(provider).rewards()
            const rewardsCount = rewardsCountBn.toNumber()

            const activeIndexes: number[] = []
            for (let i = 0; i < rewardsCount; i++) {
                const poolData: { isActive: boolean } = await sm(provider).rewardTypes(i)
                if (poolData.isActive) activeIndexes.push(i)
            }

            const earned: Array<{ rewardToken: Address; rewardAmount: BigNumber }> =
                await sm(provider).callStatic.earned(address)

            const aggregated: Record<string, BigNumber> = {}
            for (const idx of activeIndexes) {
                const { rewardToken, rewardAmount } = earned[idx] || {
                    rewardToken: '0x0',
                    rewardAmount: BigNumber.from(0),
                }
                if (rewardAmount && rewardAmount.gt(0)) {
                    const key = (rewardToken as string).toLowerCase()
                    aggregated[key] = (aggregated[key] || BigNumber.from(0)).add(rewardAmount)
                }
            }

            return Object.entries(aggregated).map(([token, amount]) => ({
                tokenAddress: token as Address,
                amount: toEtherString(amount),
            }))
        },
        async getPendingWithdrawal(
            address: Address | undefined,
            provider: Provider
        ): Promise<PendingWithdrawal | null> {
            if (!address) return null
            try {
                const result = await sm(provider).pendingWithdrawals(address)
                const amount: BigNumber = result.amount ?? result[0]
                const timestamp: BigNumber = result.timestamp ?? result[1]
                if (amount.isZero()) return null
                return {
                    amount: toEtherString(amount),
                    timestamp: timestamp.toNumber(),
                }
            } catch {
                return null
            }
        },
        async stake(signer: any, amount: string): Promise<TxResponse> {
            const c = sm(signer)
            const user = await signer.getAddress()
            const txData = await c.populateTransaction.stake(user, parseEther(amount))
            const tx = await signer.sendTransaction(txData)
            await tx.wait()
            return tx
        },
        async initiateWithdrawal(signer: any, amount: string): Promise<TxResponse> {
            const c = sm(signer)
            const txData = await c.populateTransaction.initiateWithdrawal(parseEther(amount))
            const tx = await signer.sendTransaction(txData)
            await tx.wait()
            return tx
        },
        async withdraw(signer: any): Promise<TxResponse> {
            const c = sm(signer)
            const txData = await c.populateTransaction.withdraw()
            const tx = await signer.sendTransaction(txData)
            await tx.wait()
            return tx
        },
        async cancelWithdrawal(signer: any): Promise<TxResponse> {
            const c = sm(signer)
            const txData = await c.populateTransaction.cancelWithdrawal()
            const tx = await signer.sendTransaction(txData)
            await tx.wait()
            return tx
        },
        async claimRewards(signer: any): Promise<TxResponse> {
            const c = sm(signer)
            const user = await signer.getAddress()
            const txData = await c.populateTransaction.getReward(user)
            const tx = await signer.sendTransaction(txData)
            await tx.wait()
            return tx
        },
    }
}

export type AggregatedReward = {
    tokenAddress: Address
    amount: EtherString
}

// Backward-compatible default service and wrapper exports
export const defaultStakingService = buildStakingService(
    contracts.stakingManager.address as Address,
    contracts.abis.stakingManager,
    18
)

export type PendingWithdrawal = {
    amount: EtherString
    timestamp: number
}

// Note: The canonical pending withdrawal schedule is exposed via the indexer in this app.
// This on-chain read is not specified in the current ABI; return null for now.
export async function getTotalStaked(provider: Provider): Promise<EtherString> {
    return defaultStakingService.getTotalStaked(provider)
}

export async function getStakedBalance(address: Address, provider: Provider): Promise<EtherString> {
    return defaultStakingService.getStakedBalance(address, provider)
}

export async function getCooldown(provider: Provider): Promise<number> {
    return defaultStakingService.getCooldown(provider)
}

export async function getRewards(address: Address, provider: Provider): Promise<AggregatedReward[]> {
    return defaultStakingService.getRewards(address, provider)
}

export async function getPendingWithdrawal(_address: Address, _provider: Provider): Promise<PendingWithdrawal | null> {
    return defaultStakingService.getPendingWithdrawal(_address, _provider)
}

// Write operations
export type TxResponse = { hash: string; from: string; wait: () => Promise<unknown> }

export async function stake(signer: any, amount: string): Promise<TxResponse> {
    return defaultStakingService.stake(signer, amount)
}

export async function initiateWithdrawal(signer: any, amount: string): Promise<TxResponse> {
    return defaultStakingService.initiateWithdrawal(signer, amount)
}

export async function withdraw(signer: any): Promise<TxResponse> {
    return defaultStakingService.withdraw(signer)
}

export async function cancelWithdrawal(signer: any): Promise<TxResponse> {
    return defaultStakingService.cancelWithdrawal(signer)
}

export async function claimRewards(signer: any): Promise<TxResponse> {
    return defaultStakingService.claimRewards(signer)
}

src/services/staking/client.ts.content:
import type { StakingConfig, Address } from '~/types/stakingConfig'
import { useStakeAccount } from '~/hooks/staking/useStakeAccount'
import { useStakeStats } from '~/hooks/staking/useStakeStats'
import { useStakeMutations } from '~/hooks/staking/useStakeMutations'
import { useStakingSummary } from '~/hooks/useStakingSummary'
import { buildStakingService } from '~/services/stakingService'
import { stakeQueryKeys } from '~/hooks/staking/stakeQueryKeys'

export function createStakingClient(config: StakingConfig) {
    const service = buildStakingService(config.addresses.manager as any, undefined, config.decimals)
    const keys = {
        account: (addr?: Address) => stakeQueryKeys.account(config.namespace, addr),
        stats: stakeQueryKeys.stats(config.namespace),
    }

    return {
        keys,
        useAccount: () => useStakeAccount(undefined, config.namespace, service),
        useStats: () => useStakeStats(config.namespace, service),
        useMutations: () => useStakeMutations(undefined, config.namespace ?? 'kite', service),
        useSummary: () => useStakingSummary(),
        service,
    }
}

src/config/contracts.ts.content:
import StakingManagerABI from '~/abis/StakingManager.json'
import RewardPoolABI from '~/abis/RewardPool.json'

type Address = `0x${string}`

function requireEnv(name: string): string {
    const env = import.meta.env as unknown as Record<string, string | undefined>
    const value = env[name]
    if (!value || typeof value !== 'string' || !value.startsWith('0x') || value.length < 42) {
        throw new Error(`Missing or invalid env var ${name}`)
    }
    return value
}

export const contracts = Object.freeze({
    stakingManager: {
        address: requireEnv('VITE_STAKING_MANAGER') as Address,
        abi: StakingManagerABI,
    },
    rewardDistributor: {
        address: requireEnv('VITE_REWARD_DISTRIBUTOR_ADDRESS') as Address,
        // ABI intentionally provided by incentives service until moved here
        abi: undefined as unknown as Record<string, unknown>,
    },
    tokens: {
        kite: requireEnv('VITE_KITE_ADDRESS') as Address,
        stKite: requireEnv('VITE_STAKING_TOKEN_ADDRESS') as Address,
        hai: requireEnv('VITE_HAI_ADDRESS') as Address,
        op: requireEnv('VITE_OP_ADDRESS') as Address,
    },
    abis: {
        stakingManager: StakingManagerABI,
        rewardPool: RewardPoolABI,
    },
    decimals: Object.freeze({
        KITE: 18 as const,
        ST_KITE: 18 as const,
        HAI: 18 as const,
        OP: 18 as const,
    }),
})

export type ContractsConfig = typeof contracts

